package com.codeflow.studio.config;

import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

import java.io.IOException;

/**
 * Enterprise Defense-in-Depth Security Headers Filter (OWASP Secure Headers Project / NIST SP 800-53 / CIS).
 * Guarantees that every HTTP response generated by the application includes industry-standard protection headers.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class SecurityHeadersFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        if (response instanceof HttpServletResponse httpRes) {
            // OWASP Secure Headers
            httpRes.setHeader("X-Content-Type-Options", "nosniff");
            httpRes.setHeader("X-Frame-Options", "DENY");
            httpRes.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
            httpRes.setHeader("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
            httpRes.setHeader("X-XSS-Protection", "0");
            httpRes.setHeader("X-Permitted-Cross-Domain-Policies", "none");

            // API responses must never be cached by shared proxies to prevent credential or PII leakage
            if (request instanceof HttpServletRequest httpReq && httpReq.getRequestURI().startsWith("/api/")) {
                httpRes.setHeader("Cache-Control", "no-cache, no-store, max-age=0, must-revalidate");
                httpRes.setHeader("Pragma", "no-cache");
                httpRes.setHeader("Expires", "0");
            }
        }
        chain.doFilter(request, response);
    }
}
